// Read-only query - no change tracking
var products = await _context.Products
    .AsNoTracking()
    .Where(p => p.IsActive)
    .OrderByDescending(p => p.CreatedAt)
    .ToListAsync();

// AsNoTrackingWithIdentityResolution for read with relationships
var products = await _context.Products
    .AsNoTrackingWithIdentityResolution()
    .Include(p => p.Category)
    .ToListAsync();

// Compiled query for frequently executed queries
private static readonly Func<AppDbContext, int, Task<Product?>> _getProductById =
    EF.CompileAsyncQuery((AppDbContext ctx, int id) =>
        ctx.Products.AsNoTracking().FirstOrDefault(p => p.Id == id));

// Usage
var product = await _getProductById(_context, 42);

// Bulk update without loading entities
await _context.Products
    .Where(p => p.IsDiscontinued)
    .ExecuteUpdateAsync(s => s
        .SetProperty(p => p.IsActive, false)
        .SetProperty(p => p.DiscontinuedAt, DateTime.UtcNow));

// Bulk delete
await _context.Products
    .Where(p => p.CreatedAt < DateTime.UtcNow.AddYears(-2))
    .ExecuteDeleteAsync();

// Batch inserts with AddRange
var newProducts = new List<Product> { /* 1000 products */ };
await _context.Products.AddRangeAsync(newProducts);
await _context.SaveChangesAsync();
